import itertools

def check_sumset(R, C):
    sumset = set()
    for r in R:
        for c in C:
            sumset.add(r + c)
    return sumset == set(range(1, 10))

n = 3
found = []
# Assume 0 is in R and 1 is in C
for r1 in range(1, 10):
    for r2 in range(r1 + 1, 10):
        R = {0, r1, r2}
        for c1 in range(2, 10):
            for c2 in range(c1 + 1, 10):
                C = {1, c1, c2}
                if check_sumset(R, C):
                    found.append((sorted(list(R)), sorted(list(C))))

print(found)
